// Hub: cache every board's last values, route live msgs to widgets,
// replay the selected board's cache on selection change (instant switch),
// and filter the fleet campaign list to the selected device's UID.
var t = msg.topic || '';
var cache = flow.get('sbcache') || {};    // serial -> { suffix -> {topic,payload} }
var devs  = flow.get('sbdevs')  || {};    // serial -> { online, uid }
var camplist = flow.get('camplist') || []; // last full fleet campaign list
var sel   = flow.get('sel') || '';
var buf = [[],[],[],[],[],[],[]];          // 0 diag 1 dial 2 mode 3 hum 4 light 5 fota 6 selector
var ROUTE = { 'state/uid':[0],'state/kta':[0],'state/fleet':[0],'state/fw':[0],'state/bank':[0],
              'state/fota':[0,5],'temperature':[1],'set_temp/state':[1],'heating_mode':[2],
              'humidity':[3],'light':[4] };
function emit(idxs,m){ for(var i=0;i<idxs.length;i++) buf[idxs[i]].push(m); }
function replay(s){ var cc = cache[s] || {}; Object.keys(cc).forEach(function(suf){
    if (ROUTE[suf]) emit(ROUTE[suf], { topic: cc[suf].topic, payload: cc[suf].payload }); }); }
function firstOnline(){ var on = Object.keys(devs).filter(function(x){ return devs[x].online; }).sort(); return on[0] || ''; }
function selUid(){ return (sel && devs[sel]) ? (devs[sel].uid || '') : ''; }
function filterCamps(rows, uid){ uid = (uid || '').toUpperCase();
    return (rows || []).filter(function(r){ if (!r) return false; var ru = String(r.uid || '').toUpperCase();
        return ru === '' || (uid && ru === uid); }); }  // no metadata -> global (shown for all)
function pushCamps(){ emit([5], { topic:'campaign/list', payload: filterCamps(camplist, selUid()) }); }
var render = false;

if (msg.payload && typeof msg.payload === 'object' && msg.payload.select) {
    // dropdown selection -> switch + instant replay + re-filter campaigns
    if (devs[msg.payload.select]) { sel = msg.payload.select; flow.set('sel', sel); }
    replay(sel); pushCamps(); render = true;
} else if (t.indexOf('crypto_auth/') === 0) {
    var p = t.split('/'); var s = p[1]; var suf = p.slice(2).join('/');
    if (!s) return null;
    if (suf === 'state/uid') { if(!devs[s]) devs[s]={online:false}; devs[s].uid=String(msg.payload); render=true; }
    else if (suf === 'lwt') { if(!devs[s]) devs[s]={}; devs[s].online=(String(msg.payload).trim()==='online'); render=true; }
    if (suf !== 'lwt') { if(!cache[s]) cache[s]={}; cache[s][suf]={topic:t, payload:msg.payload}; }
    // selection: alphabetical-first at startup; never stolen by a new board;
    // auto-fail-over to the alphabetical-first ONLINE board if the selected one is offline.
    var prev = sel;
    if (!sel || !devs[sel]) { sel = Object.keys(devs).sort()[0] || ''; flow.set('sel', sel); render=true; }
    else if (!devs[sel].online) { var fo = firstOnline(); if (fo && fo !== sel) { sel = fo; flow.set('sel', sel); render=true; } }
    if (sel !== prev) { replay(sel); pushCamps(); }   // auto-switch -> repaint + re-filter campaigns
    if (s === sel && ROUTE[suf]) emit(ROUTE[suf], msg);
} else if (t === 'campaign/list') {
    var rows; try { rows = (typeof msg.payload === 'string') ? JSON.parse(msg.payload) : msg.payload; } catch(e) { rows = []; }
    camplist = rows || []; flow.set('camplist', camplist);
    emit([5], { topic: t, payload: filterCamps(camplist, selUid()) });   // only the selected device's campaigns
} else {
    emit([5], msg);   // campaign/busy, campaign/log : fleet-level, straight through
}

flow.set('sbcache', cache);
flow.set('sbdevs', devs);
if (render) {
    var list = Object.keys(devs).sort().map(function(x){ return { serial:x, online:!!devs[x].online }; });
    buf[6].push({ topic:'render', payload:{ devices:list, sel:sel } });
}
var out = [];
for (var i=0;i<7;i++) out.push(buf[i].length ? (buf[i].length===1?buf[i][0]:buf[i]) : null);
return out;
